/// The position, rendered. Gaps are not a footnote — they are why a figure is missing.
/// Truncate to at most `n` CHARACTERS, never bytes.
///
/// `&s[..22]` panics when byte 22 lands inside a multi-byte character, and a statement description is
/// exactly where that arrives: a merchant with an accent, a currency symbol, a non-Latin name. The
/// crash would be in the RENDERER, so the analysis would be correct and the command would still die.
pub(crate) fn clip(s: &str, n: usize) -> String {
    if s.chars().count() <= n { s.to_string() } else { s.chars().take(n).collect() }
}
